arguments.command:
curl -sS -X POST https://api.linear.app/graphql -H 'Content-Type: application/json' -H 'Authorization: Bearer <TOKEN>' -d '{"query":"{ __schema { mutationType { fields { name args { name type { name kind ofType { name kind ofType { name } } } } } } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
for f in d['data']['__schema']['mutationType']['fields']:
    for a in f['args']:
        t=a['type'] or {}
        inner=(t.get('ofType') or {})
        name=t.get('name') or inner.get('name')
        if name and 'Team' in name and 'Input' in name:
            print(f['name'], '->', a['name'], name)
"

